// Compare two 3MF/ZIP files or two folders of them entry by entry (names, order, uncompressed bytes).
// npx tsx scripts/compare-3mf.ts A.3mf B.3mf      or      npx tsx scripts/compare-3mf.ts DIR_A DIR_B
// ZIP bytes always differ between runs (entry timestamps; compression of entries copied unchanged from the
// source), so equality is defined on the stored content. Also compares the .json reports next to each file.
// Entries that only differ in the generated date/time (CreationDate/ModificationDate metadata, the PrusaSlicer
// config's "; generated by ... on DATE at TIME UTC" line) count as identical and are listed as date-only.
import { readFileSync, readdirSync, statSync, existsSync } from "node:fs";
import { unzipSync, strFromU8 } from "fflate";

const [a, b] = process.argv.slice(2);
if (!a || !b) throw Error("usage: compare-3mf.ts A B");
const pairs: [string, string][] = statSync(a).isDirectory()
  ? readdirSync(a).filter((f) => f.endsWith(".3mf")).sort().map((f) => [`${a}/${f}`, `${b}/${f}`])
  : [[a, b]];
let bad = 0;
const DATE = /<metadata name="(?:CreationDate|ModificationDate)">[^<]*<\/metadata>|^; generated by .* on \d{4}-\d\d-\d\d at [\d:]+ UTC$/gm;
for (const [x, y] of pairs) {
  const name = x.split("/").pop();
  if (!existsSync(y)) { console.log(`MISSING ${name}`); bad++; continue; }
  const order = (buf: Uint8Array) => { const names: string[] = []; unzipSync(buf, { filter: (f) => { names.push(f.name); return false; } }); return names; };
  const bx = new Uint8Array(readFileSync(x)), by = new Uint8Array(readFileSync(y));
  const za = unzipSync(bx), zb = unzipSync(by);
  const oa = order(bx), ob = order(by);
  const diffs: string[] = [];
  if (oa.join("\n") !== ob.join("\n")) diffs.push(`entry list/order differs: ${oa.length} vs ${ob.length}`);
  for (const k of oa) {
    if (!zb[k]) { diffs.push(`only in A: ${k}`); continue; }
    const u = za[k], v = zb[k];
    if (u.length === v.length && Buffer.from(u).equals(Buffer.from(v))) continue;
    const su = strFromU8(u), sv = strFromU8(v);
    if (su.replace(DATE, "") === sv.replace(DATE, "")) { diffs.push(`date-only: ${k}`); continue; }
    diffs.push(`content differs: ${k} (${u.length} vs ${v.length} bytes)`);
  }
  const ja = x.replace(/\.3mf$/, ".json"), jb = y.replace(/\.3mf$/, ".json");
  if (existsSync(ja) && existsSync(jb) && readFileSync(ja, "utf8") !== readFileSync(jb, "utf8")) diffs.push("report json differs");
  const hard = diffs.filter((d) => !d.startsWith("date-only"));
  if (hard.length) bad++;
  console.log(`${hard.length ? "DIFF" : "SAME"} ${name}${diffs.length ? "  " + diffs.join("; ") : ""}`);
}
console.log(`${pairs.length - bad}/${pairs.length} identical`);
process.exit(bad ? 1 : 0);
